(function(){
  'use strict';
  const all=window.ACTOR_ALIAS_REGISTRY.scenes;
  const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const record=(context,track)=>all[context]?.actors[track]||null;
  const actor=(context,track)=>record(context,track)?.alias||null;
  const scene=context=>all[context]?.display_name||('Waymo · '+context);
  const sceneKey=context=>all[context]?.scene_key||context;
  function rows(context){const entry=all[context];if(!entry)return [];return Object.entries(entry.actors).map(([track,row])=>({scene:entry.display_name,scene_key:entry.scene_key,context_id:context,actor_alias:row.alias,track_id:track,native_asset_index:row.native_asset_index??null,alias_origin:row.alias_origin})).sort((a,b)=>Number(a.actor_alias.slice(1))-Number(b.actor_alias.slice(1)));}
  function renderMap(container,context,onSelect){
    if(!container)return;container.replaceChildren();const note=document.createElement('p');note.textContent='aN 是本场景内固定的沟通代号，不是 Waymo 官方编号或候选排名。跨场景沟通时请同时带场景号和分区。';container.append(note);
    const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['车辆代号','原始轨迹 ID','已绑定资产序号']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);
    for(const row of rows(context)){const tr=document.createElement('tr'),code=document.createElement('td'),raw=document.createElement('td'),native=document.createElement('td');if(onSelect){const button=document.createElement('button');button.textContent=row.actor_alias;button.addEventListener('click',()=>onSelect(row.track_id));code.append(button);}else code.textContent=row.actor_alias;raw.textContent=row.track_id;native.textContent=row.native_asset_index==null?'—':String(row.native_asset_index);tr.append(code,raw,native);table.append(tr);}container.append(table);
  }
  window.ActorNames={record,actor,scene,sceneKey,rows,renderMap,escape};
})();
